const grid = document.getElementById('grid');
const featuredGrid = document.getElementById('featuredGrid');
const empty = document.getElementById('empty');
const stats = document.getElementById('stats');
const q = document.getElementById('q');
const audio = document.getElementById('audio');
const suggestions = document.getElementById('suggestions');
const loadMore = document.getElementById('loadMore');
const esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const params = new URLSearchParams(location.search);
if (params.get('q')) q.value = params.get('q');

let quickFilter = '';
let renderedCount = 0;
let currentList = [];
const PAGE_SIZE = 48;
const FEATURED_SIZE = 10;
const searchIndex = MOVIES.map((m, index) => ({
  m,
  index,
  bag: normalizeText(m.title + ' ' + m.magnets.map(l => l.label).join(' ') + ' ' + m.badges.map(b => b[1]).join(' ')),
  title: normalizeText(m.title)
}));

function normalizeText(value) {
  return String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, ' ');
}
function ratingFor(m) {
  let n = 0;
  for (const ch of m.title) n = (n + ch.charCodeAt(0)) % 41;
  return (5 + n / 10).toFixed(1).replace('.0','');
}
function editDistance(a, b) {
  if (a === b) return 0;
  if (!a || !b) return Math.max(a.length, b.length);
  if (Math.abs(a.length - b.length) > 2) return 3;
  const prev = Array.from({length: b.length + 1}, (_, i) => i);
  const curr = new Array(b.length + 1);
  for (let i = 1; i <= a.length; i++) {
    curr[0] = i;
    let rowMin = curr[0];
    for (let j = 1; j <= b.length; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      curr[j] = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
      rowMin = Math.min(rowMin, curr[j]);
    }
    if (rowMin > 2) return 3;
    for (let j = 0; j <= b.length; j++) prev[j] = curr[j];
  }
  return prev[b.length];
}
function tokenScore(token, words, bag) {
  if (!token) return 0;
  if (bag.includes(token)) return 10;
  let best = 99;
  for (const w of words) {
    if (w.includes(token) || token.includes(w)) return 8;
    if (Math.abs(w.length - token.length) <= 2) best = Math.min(best, editDistance(token, w));
  }
  const limit = token.length <= 4 ? 1 : 2;
  return best <= limit ? 5 - best : -1;
}
function scoreIndexed(item, cleanTerm) {
  if (!cleanTerm) return 1;
  const words = item.bag.split(' ');
  const tokens = cleanTerm.split(' ').filter(Boolean);
  let score = 0;
  for (const token of tokens) {
    const s = tokenScore(token, words, item.bag);
    if (s < 0) return -1;
    score += s;
  }
  if (item.title.includes(cleanTerm)) score += 25;
  if (item.title.startsWith(cleanTerm)) score += 15;
  return score;
}
function passesFilters(item) {
  const au = normalizeText(audio.value);
  const quick = normalizeText(quickFilter);
  if (au && !item.bag.includes(au)) return false;
  if (quick && !item.bag.includes(quick)) return false;
  return true;
}
function filteredMovies() {
  const cleanTerm = normalizeText(q.value.trim());
  const scored = [];
  for (const item of searchIndex) {
    if (!passesFilters(item)) continue;
    const score = scoreIndexed(item, cleanTerm);
    if (score >= 0) scored.push({item, score});
  }
  if (cleanTerm) scored.sort((a, b) => b.score - a.score || a.item.index - b.item.index);
  return scored.map(x => x.item.m);
}
function downloadUrl(m, idx) {
  return 'start.php?id=' + encodeURIComponent(m._slug) + '&link=' + encodeURIComponent(idx || 0);
}
function card(m, compact=false, eager=false) {
  const badges = m.badges.map(b => '<span class="badge ' + b[0] + '">' + esc(b[1]) + '</span>').join('');
  const magnets = compact ? '' : m.magnets.map((l, idx) => '<a rel="nofollow" href="' + downloadUrl(m, idx) + '">' + esc(l.label.replace(/^\W+/, '')) + '</a>').join('');
  let extra = '';
  if (!compact && m.magnets.length > 1) extra = '<details><summary>+ ' + (m.magnets.length - 1) + ' link(s) magnet</summary><div class="links">' + magnets + '</div></details>';
  else if (!compact && m.magnets.length === 1) extra = '<details><summary>+ detalhes do link</summary><div class="links">' + magnets + '</div></details>';
  const trailer = compact ? '' : m.other.map(l => '<a class="trailer" href="' + esc(l.url) + '" target="_blank" rel="nofollow noopener noreferrer">' + esc(l.label) + '</a>').join('');
  const date = m.date ? '<time class="date" datetime="' + esc(m.date) + '">' + esc(m.date.slice(0,4)) + '</time>' : '';
  const magnetHref = m.magnets.length ? esc(downloadUrl(m, 0)) : '#';
  const quality = (m.badges.find(b => b[0] === 'q') || ['', ''])[1];
  const audioInfo = (m.badges.find(b => b[0] === 'a') || ['', ''])[1];
  const label = esc(m.title + (quality ? ' - ' + quality : '') + (audioInfo ? ' - ' + audioInfo : ''));
  const loading = eager ? 'eager' : 'lazy';
  const fetchPriority = eager ? ' fetchpriority="high"' : '';
  return '<article id="' + esc(m._slug) + '" class="card" role="listitem" itemscope itemtype="https://schema.org/Movie" aria-label="' + label + '">' +
    '<meta itemprop="url" content="#' + esc(m._slug) + '">' +
    '<div class="thumb"><img itemprop="image" loading="' + loading + '" decoding="async"' + fetchPriority + ' src="' + esc(m.poster) + '" alt="Capa do filme ' + esc(m.title) + '" title="' + esc(m.title) + '"><span class="rating">' + ratingFor(m) + '</span><div class="badges">' + badges + '</div>' + date + '</div>' +
    '<div class="info"><h2 itemprop="name">' + esc(m.title) + '</h2>' +
      '<p class="sr-only" itemprop="description">' + label + '. Confira trailer e opções oficiais de download autorizadas.</p>' +
      '<div class="actions"><a class="btn magnet" rel="nofollow" href="' + magnetHref + '" aria-label="Baixar ' + esc(m.title) + '">🧲 Baixar</a>' + extra + trailer + '</div>' +
    '</div></article>';
}
function renderFeatured() {
  const top = MOVIES.slice(0, FEATURED_SIZE);
  featuredGrid.innerHTML = top.map((m, i) => card(m, true, i < 4)).join('');
}
function updateLoadMore() {
  loadMore.hidden = renderedCount >= currentList.length;
  loadMore.textContent = 'Carregar mais filmes (' + Math.max(0, currentList.length - renderedCount) + ')';
}
function renderPage(reset=false) {
  if (reset) {
    renderedCount = 0;
    grid.innerHTML = '';
  }
  const next = currentList.slice(renderedCount, renderedCount + PAGE_SIZE);
  const html = next.map((m, i) => card(m, false, renderedCount + i < 8)).join('');
  if (reset) grid.innerHTML = html;
  else grid.insertAdjacentHTML('beforeend', html);
  renderedCount += next.length;
  empty.style.display = currentList.length ? 'none' : 'block';
  stats.textContent = currentList.length + ' de ' + MOVIES.length + ' filmes';
  updateLoadMore();
}
function renderSuggestions() {
  const term = q.value.trim();
  if (!normalizeText(term) || normalizeText(term).length < 2) {
    suggestions.classList.remove('show'); suggestions.innerHTML = ''; return;
  }
  const list = currentList.slice(0, 8);
  if (!list.length) {
    suggestions.innerHTML = '<div class="suggestion-empty">Nenhuma recomendação encontrada. Tente outro nome.</div>';
    suggestions.classList.add('show'); return;
  }
  suggestions.innerHTML = list.map(m => {
    const quality = (m.badges.find(b => b[0] === 'q') || ['', ''])[1] || 'Filme';
    const audioInfo = (m.badges.find(b => b[0] === 'a') || ['', ''])[1] || '';
    return '<button type="button" class="suggestion-item" role="option" data-title="' + esc(m.title) + '"><img src="' + esc(m.poster) + '" loading="lazy" alt=""><span><span class="suggestion-title">' + esc(m.title) + '</span><span class="suggestion-meta">' + esc([quality, audioInfo].filter(Boolean).join(' • ')) + '</span></span><span class="suggestion-tag">Ver</span></button>';
  }).join('');
  suggestions.classList.add('show');
}
function render(reset=true) {
  currentList = filteredMovies();
  requestAnimationFrame(() => {
    renderPage(reset);
    renderSuggestions();
    const term = q.value.trim();
    document.title = normalizeText(term) ? ('Busca por ' + term + ' | Filmes 2026') : 'Filmes 2026: Lançamentos, Trailers e Downloads Oficiais';
  });
}
function updateUrl() {
  const url = new URL(location.href);
  q.value.trim() ? url.searchParams.set('q', q.value.trim()) : url.searchParams.delete('q');
  history.replaceState(null, '', url);
}
document.querySelectorAll('.pill').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.pill').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    quickFilter = (btn.dataset.filter || '').toLowerCase();
    render(true);
    document.getElementById('latest-title').scrollIntoView({behavior:'smooth', block:'start'});
  });
});
suggestions.addEventListener('click', e => {
  const btn = e.target.closest('.suggestion-item');
  if (!btn) return;
  q.value = btn.dataset.title || '';
  suggestions.classList.remove('show');
  updateUrl(); render(true);
  document.getElementById('latest-title').scrollIntoView({behavior:'smooth', block:'start'});
});
document.addEventListener('click', e => { if (!e.target.closest('.search-panel')) suggestions.classList.remove('show'); });
q.addEventListener('input', () => { updateUrl(); render(true); });
q.addEventListener('focus', () => { currentList = filteredMovies(); renderSuggestions(); });
audio.addEventListener('change', () => render(true));
loadMore.addEventListener('click', () => requestAnimationFrame(() => renderPage(false)));
renderFeatured();
render(true);
